.task-row span { overflow-wrap: anywhere; }
.task-completion { display: flex; align-items: center; }
.task-completion input { width: 1.25rem; height: 1.25rem; min-height: auto; }
.alert { color: #b91c1c; }
.alert[hidden] { display: none; }

@media (max-width: 30rem) {
  .shell { margin: 1rem auto; padding: 1.25rem; }
